  await mockDetails(backend);
  const huge = "9".repeat(100) + ".123456789";
  const sources = [
    { funder: { id: funderId, name: "Example Research Foundation and International Policy Advisory Partnership" }, amount: huge, currency: "GBP", payment_type: null },
    { funder: { id: "22222222-2222-4222-8222-222222222222", name: "Community Trust" }, amount: "12500.50", currency: "GBP", payment_type: null },
