  await backend.route("**/api/members/1", route => route.fulfill({ json: { ...memberDetails, declarations: [{ ...memberDetails.declarations[0], category_id: 999, category_name: "Other", registered_at: null, entries: sources }] } }));
  await page.goto("/members/1?q=Example");
